window.SCHOOL_LISTENING={"../assets/media/5b8d0c8544211fb9d6bc12c80234eeef403d5fe063cdf54b9f4be03fd4c8f3d1.mp3":[{"id":"PPT_5b8d0c8544211fb9","audioId":"PPT_5b8d0c8544211fb9","title":"Book 2 · Unit 2 · LS · LISTENING 1","subtitle":"LISTENING 1 · source slide 47","duration":378.23,"cues":[{"start":0,"end":1.84,"text":"Unit two,","coverage":1},{"start":2.16,"end":3.6,"text":"two .one","coverage":1},{"start":4.88,"end":13.82,"text":"Today, I'm at the Vivid Sydney Festival, which has been held in Australia every year since 2009.","coverage":1},{"start":14.06,"end":18,"text":"It's held for three weeks during May and June.","coverage":1},{"start":18.46,"end":23.24,"text":"It has loads of activities with music, food, art and learning.","coverage":1},{"start":23.98,"end":26.08,"text":"Anybody can go to the lectures,","coverage":1},{"start":26.46,"end":29.28,"text":"see the lights and eat interesting food.","coverage":1},{"start":29.28,"end":31.86,"text":"Many activities are free.","coverage":1},{"start":32.5,"end":35.16,"text":"The festival gets bigger every year.","coverage":1},{"start":35.6,"end":38.88,"text":"Sometimes over two million people come.","coverage":1},{"start":39.64,"end":42.88,"text":"We asked one of the visitors about the festival.","coverage":1},{"start":43.72,"end":43.84,"text":"Hello","coverage":1},{"start":43.84,"end":44.44,"text":"there.","coverage":1},{"start":44.86,"end":51.36,"text":"Can you introduce yourself and tell me, is this your first time at the festival here in Sydney?","coverage":1},{"start":52.4,"end":54.34,"text":"My name is Olivia and no,","coverage":1},{"start":54.74,"end":56.04,"text":"I come here every year.","coverage":1},{"start":56.72,"end":59.22,"text":"Why do you like coming to the festival?","coverage":1},{"start":60.26,"end":62.82,"text":"Well, it's an interesting event to come to.","coverage":1},{"start":63.16,"end":65.84,"text":"It's great for children and adults.","coverage":1},{"start":66.86,"end":71.72,"text":"I enjoy learning about all the new ideas people have on important topics.","coverage":1},{"start":72.54,"end":81.12,"text":"We don't get much time to really think or learn about new things in everyday life, but you can do exactly that at this festival.","coverage":1},{"start":81.92,"end":85.8,"text":"So what kinds of things do people learn and do here?","coverage":1},{"start":86.18,"end":88.96,"text":"Do people try mainly one type of thing?","coverage":1},{"start":89.88,"end":90.36,"text":"No,","coverage":1},{"start":90.7,"end":93.08,"text":"most people plan on going to several events.","coverage":1},{"start":93.72,"end":96.36,"text":"For example, today I learned about nature.","coverage":1},{"start":97.12,"end":100.8,"text":"I went to a lecture about the sea and new ways to clean it.","coverage":1},{"start":101.36,"end":102.54,"text":"It's quite interesting.","coverage":1},{"start":103.42,"end":106.2,"text":"Yesterday, I walked around a 3D art show.","coverage":1},{"start":106.86,"end":109.38,"text":"The entire room was covered in pictures.","coverage":1},{"start":109.38,"end":111.64,"text":"It was an exciting activity.","coverage":1},{"start":112.42,"end":115.24,"text":"It felt like flying over the trees and mountains.","coverage":1},{"start":116.12,"end":121.26,"text":"And tomorrow, I'm going to a talk on how food can help people live better lives,","coverage":1},{"start":121.7,"end":124,"text":"which I'm sure will really make me think.","coverage":1},{"start":125.28,"end":128.1,"text":"Are there any things you don't like about it?","coverage":1},{"start":128.56,"end":129.68,"text":"Are you ever bored?","coverage":1},{"start":130.66,"end":131.4,"text":"Not really.","coverage":1},{"start":132.1,"end":134.74,"text":"The only problem is that it's really crowded.","coverage":1},{"start":135.84,"end":138,"text":"Olivia, like many others,","coverage":1},{"start":138.38,"end":141.5,"text":"is really enjoying the Vivid Sydney Festival.","coverage":1},{"start":142.1,"end":142.72,"text":"Nowadays,","coverage":1},{"start":143.06,"end":146,"text":"around the world, there are many festivals,","coverage":1},{"start":146.5,"end":148.3,"text":"often based on nature,","coverage":1},{"start":148.66,"end":149.92,"text":"food, or culture.","coverage":1},{"start":150.64,"end":154.58,"text":"Take the Cherry Blossom Festival in Japan, for example.","coverage":1},{"start":155.22,"end":156.08,"text":"In Tokyo,","coverage":1},{"start":156.44,"end":157.72,"text":"the capital of Japan,","coverage":1},{"start":158.16,"end":161.68,"text":"the Cherry Blossom Festival is held in early April.","coverage":1},{"start":161.68,"end":165.46,"text":"It is an important festival celebrating nature.","coverage":1},{"start":166.16,"end":173.7,"text":"The actual dates change every year because the celebration happens only when the trees have cherry blossoms.","coverage":1},{"start":174.18,"end":184.38,"text":"So it is a little different from a festival that has the same date every year, and it's not organized in the same way as many other festivals.","coverage":1},{"start":185.2,"end":189.42,"text":"Our reporter, Mike Pearce, went to Tokyo to find out.","coverage":1},{"start":190.24,"end":192.48,"text":"Today I am talking with Yuki.","coverage":1},{"start":193.24,"end":197.74,"text":"She sells food during the Cherry Blossom Festival in Ueno Park in Tokyo.","coverage":1},{"start":198.46,"end":199.6,"text":"Hi, Yuki.","coverage":1},{"start":200.5,"end":200.82,"text":"Hi.","coverage":1},{"start":201.38,"end":203.94,"text":"Welcome to the Cherry Blossom Festival.","coverage":1},{"start":204.94,"end":205.4,"text":"Thanks.","coverage":1},{"start":206.16,"end":207.9,"text":"So what happens here?","coverage":1},{"start":208.82,"end":210.9,"text":"Well, as you can see,","coverage":1},{"start":211.22,"end":213.22,"text":"it's a cherry blossom festival.","coverage":1},{"start":213.88,"end":217.88,"text":"It is a celebration of spring and the cherry flowers.","coverage":1},{"start":217.88,"end":223.08,"text":"So it doesn't have specific activities that people do.","coverage":1},{"start":223.82,"end":224.2,"text":"Instead,","coverage":1},{"start":224.64,"end":230.24,"text":"people come to enjoy the cherry blossoms and have a picnic under the trees.","coverage":1},{"start":231.12,"end":236.4,"text":"We have about a thousand trees full of beautiful flowers.","coverage":1},{"start":237.76,"end":240.62,"text":"Do you have many people here from other countries?","coverage":1},{"start":241.66,"end":242.26,"text":"Yes.","coverage":1},{"start":242.74,"end":246.08,"text":"Our visitors are from all over the world.","coverage":1},{"start":246.64,"end":248.98,"text":"In addition to the cherry blossoms,","coverage":1},{"start":249.28,"end":251.42,"text":"there are lots of food stalls,","coverage":1},{"start":251.92,"end":255.42,"text":"and people can hire a boat to go around the lake,","coverage":1},{"start":255.92,"end":255.96,"text":"too.","coverage":1},{"start":256.62,"end":260.36,"text":"There are many beautiful natural places here.","coverage":1},{"start":260.84,"end":264.9,"text":"Some people prefer to visit some of the park's many museums,","coverage":1},{"start":265.28,"end":271.8,"text":"but I think Tokyo is one of the best places to come for the Cherry Blossom Festival.","coverage":1},{"start":272.82,"end":275.32,"text":"Well, I hope you enjoy the rest of the event.","coverage":1},{"start":276.82,"end":281,"text":"Visiting such festivals is not just for entertainment.","coverage":1},{"start":281.42,"end":287.76,"text":"It's also a fantastic way to find out about the culture of a different country.","coverage":1},{"start":288.46,"end":293.54,"text":"I went to Oman in the Middle East recently to do just that.","coverage":1},{"start":294.42,"end":300.4,"text":"I'm here in Muscat at the Festival of Culture and Heritage talking to Nasra.","coverage":1},{"start":300.4,"end":305.66,"text":"She is visiting the festival Muscat Nights with her family.","coverage":1},{"start":306.64,"end":311.68,"text":"The event is held in January and February each year in Oman,","coverage":1},{"start":312.34,"end":316.12,"text":"and Nasra has been coming for the last couple of years.","coverage":1},{"start":316.7,"end":317.62,"text":"Hi, Nasra.","coverage":1},{"start":317.9,"end":319.78,"text":"Are you enjoying the festival?","coverage":1},{"start":320.82,"end":322.8,"text":"Yes, it's wonderful.","coverage":1},{"start":324.02,"end":326.78,"text":"Can you tell us something about the festival?","coverage":1},{"start":326.78,"end":328.58,"text":"Of course.","coverage":1},{"start":329.12,"end":333.14,"text":"It's a chance for people to learn about the heritage and culture of Oman.","coverage":1},{"start":334.26,"end":335.92,"text":"So why are you here?","coverage":1},{"start":336.78,"end":339.36,"text":"My mother and father want to watch some of the sports.","coverage":1},{"start":339.98,"end":343.1,"text":"There was basketball last year and also a car race.","coverage":1},{"start":343.82,"end":345.82,"text":"You can listen to traditional music,","coverage":1},{"start":346.6,"end":348.96,"text":"but I decided to go to the fashion show.","coverage":1},{"start":349.68,"end":351.02,"text":"That sounds great.","coverage":1},{"start":351.02,"end":352.1,"text":"Yeah.","coverage":1},{"start":352.98,"end":355.62,"text":"And after we finish watching the races and shows,","coverage":1},{"start":356,"end":358,"text":"we'll go and eat some traditional food.","coverage":1},{"start":358.96,"end":360.32,"text":"Sounds amazing.","coverage":1},{"start":360.86,"end":363.1,"text":"I hope you all have a great time.","coverage":1},{"start":364.2,"end":368.12,"text":"So these international festivals with lots of music,","coverage":1},{"start":368.44,"end":373.54,"text":"food and fashion are providing a different type of experience for people.","coverage":1},{"start":374.3,"end":377.78,"text":"Next week, we'll be looking at...","coverage":1}],"file":"1e9fda57179879062c9a.js","track":0,"media":"../assets/media/5b8d0c8544211fb9d6bc12c80234eeef403d5fe063cdf54b9f4be03fd4c8f3d1.mp3"}],"../assets/media/ec22923bcd1d5dbaa38ff63e68d7cd88f6fb2045a010b9700b895353506b8fe8.mp3":[{"id":"PPT_ec22923bcd1d5dba","audioId":"PPT_ec22923bcd1d5dba","title":"Book 2 · Unit 2 · LS · LISTENING 1","subtitle":"LISTENING 1 · source slide 54","duration":7.5,"cues":[{"start":0,"end":1.74,"text":"two .two","coverage":1},{"start":2.68,"end":5.64,"text":"I went to a lecture about the sea.","coverage":1}],"file":"48d4524ee486e54cf53c.js","track":0,"media":"../assets/media/ec22923bcd1d5dbaa38ff63e68d7cd88f6fb2045a010b9700b895353506b8fe8.mp3"}],"../assets/media/f38f5acd0115544835b2ae43002350b8894194e7a261b159e930e575ab781635.mp3":[{"id":"PPT_f38f5acd01155448","audioId":"PPT_f38f5acd01155448","title":"Book 2 · Unit 2 · LS · LISTENING 2","subtitle":"LISTENING 2 · source slide 79","duration":225.31,"cues":[{"start":0,"end":2.48,"text":"two .four","coverage":1},{"start":3,"end":3.7,"text":"Paul,","coverage":1},{"start":4.14,"end":6.6,"text":"you have cousins in the US, don't you?","coverage":1},{"start":7.34,"end":8.44,"text":"What's your opinion?","coverage":1},{"start":9.28,"end":12.72,"text":"Which is the best North American holiday or celebration?","coverage":1},{"start":13.74,"end":14.54,"text":"Hmm.","coverage":1},{"start":15.04,"end":15.56,"text":"Well,","coverage":1},{"start":16.08,"end":20.16,"text":"I like Independence Day in the US because of the fireworks,","coverage":1},{"start":20.66,"end":23.62,"text":"and New Year's Eve often has fireworks too.","coverage":1},{"start":24.36,"end":27.22,"text":"But I think the best holiday is Thanksgiving.","coverage":1},{"start":27.22,"end":29.54,"text":"Why do you like Thanksgiving?","coverage":1},{"start":31,"end":33.32,"text":"Everyone has something to be thankful for,","coverage":1},{"start":33.88,"end":35.96,"text":"so everyone can celebrate it.","coverage":1},{"start":36.6,"end":39.44,"text":"Both the US and Canada celebrate it.","coverage":1},{"start":39.94,"end":40.4,"text":"Really?","coverage":1},{"start":41.08,"end":42.86,"text":"How do people celebrate it?","coverage":1},{"start":43.78,"end":48.7,"text":"Well, most people get together with family and friends and have a big meal.","coverage":1},{"start":49.58,"end":50.74,"text":"What do they eat?","coverage":1},{"start":50.74,"end":53.66,"text":"They usually eat a traditional meal.","coverage":1},{"start":54.2,"end":58.56,"text":"This is usually a delicious turkey with stuffing for the main dish.","coverage":1},{"start":59.34,"end":60.6,"text":"You should try it.","coverage":1},{"start":61.4,"end":65.68,"text":"Most traditional Thanksgiving meals have food which is from the Americas,","coverage":1},{"start":66.48,"end":67.68,"text":"like potatoes,","coverage":1},{"start":68.02,"end":69.74,"text":"corn and cranberries.","coverage":1},{"start":71.06,"end":73.3,"text":"For dessert they eat pumpkin pie,","coverage":1},{"start":73.78,"end":76.36,"text":"but some people prefer different kinds of pie,","coverage":1},{"start":76.8,"end":77.64,"text":"like apple.","coverage":1},{"start":77.64,"end":81.06,"text":"Is the food the same in both countries?","coverage":1},{"start":82.28,"end":85.2,"text":"Actually, there are some differences in the food.","coverage":1},{"start":86.02,"end":89.72,"text":"In Canada, for example, the pumpkin pie is spicy,","coverage":1},{"start":90.1,"end":92.2,"text":"but in the US it's sweet.","coverage":1},{"start":93.32,"end":96.44,"text":"I like the American style with whipped cream.","coverage":1},{"start":96.94,"end":98.38,"text":"You have to try it.","coverage":1},{"start":98.38,"end":101.44,"text":"Another dish which is different is the stuffing.","coverage":1},{"start":102.24,"end":110.22,"text":"For instance, in Canada stuffing is often made from rice or bread, but in the southern US it could be made from cornbread.","coverage":1},{"start":111.24,"end":112.46,"text":"In the eastern US,","coverage":1},{"start":112.9,"end":114.8,"text":"sometimes oysters are used in the stuffing.","coverage":1},{"start":116.14,"end":118,"text":"That all sounds delicious.","coverage":1},{"start":118.8,"end":121.72,"text":"Are there any special decorations for Thanksgiving?","coverage":1},{"start":122.72,"end":123.2,"text":"Well,","coverage":1},{"start":123.62,"end":128.58,"text":"people often decorate their dinner tables and homes with things such as colourful leaves,","coverage":1},{"start":128.92,"end":130.66,"text":"autumn vegetables and candles.","coverage":1},{"start":131.48,"end":136.1,"text":"The decorations usually have autumn colours like red, yellow and orange.","coverage":1},{"start":137.2,"end":140.98,"text":"Do people give gifts or do some special activities?","coverage":1},{"start":141.98,"end":146.92,"text":"Well, people don't really give gifts, but there are some special activities.","coverage":1},{"start":147.44,"end":153.42,"text":"For example, both countries celebrate with parades, with marching bands and people in costumes.","coverage":1},{"start":154.32,"end":157.1,"text":"It's also traditional to watch sport on TV.","coverage":1},{"start":158.12,"end":162.12,"text":"It sounds like the celebration is almost the same in both countries.","coverage":1},{"start":163.2,"end":167.4,"text":"Well, there are some differences between Canadian and American Thanksgiving.","coverage":1},{"start":168.62,"end":169.24,"text":"Like what?","coverage":1},{"start":169.24,"end":175.3,"text":"Well, for instance, in Canada the holiday is celebrated on the second Monday in October,","coverage":1},{"start":175.9,"end":179.18,"text":"but in the US it's on the fourth Thursday in November.","coverage":1},{"start":180.36,"end":185.04,"text":"Another difference is that in Canada people enjoy small local parades.","coverage":1},{"start":185.88,"end":193.18,"text":"In the US they have a huge parade in New York City and people all over the US watch it on TV.","coverage":1},{"start":193.18,"end":197.42,"text":"People in the New York parade sometimes wear costumes.","coverage":1},{"start":198.14,"end":202.54,"text":"One last difference is that each country has different reasons for the holiday.","coverage":1},{"start":203.28,"end":206.98,"text":"In Canada the holiday celebrates the autumn harvest,","coverage":1},{"start":207.74,"end":215.98,"text":"but Americans celebrate the autumn harvest and remembering the Native Americans helping settlers hunt and learn to grow food.","coverage":1},{"start":216.64,"end":219.06,"text":"That sounds like a lot of fun.","coverage":1},{"start":219.74,"end":223.32,"text":"I want to go to a Thanksgiving celebration in both countries.","coverage":1}],"file":"6908e404109047bfafbb.js","track":0,"media":"../assets/media/f38f5acd0115544835b2ae43002350b8894194e7a261b159e930e575ab781635.mp3"}],"../assets/media/fd35f29335a7295adf34b3bc8ac90d93556ff2d513ca30f629bc998e74845ff8.mp3":[{"id":"PPT_fd35f29335a7295a","audioId":"PPT_fd35f29335a7295a","title":"Book 2 · Unit 2 · LS · LISTENING 1","subtitle":"LISTENING 1 · source slide 57","duration":23.35,"cues":[{"start":0,"end":2.26,"text":"two .three","coverage":1},{"start":3.4,"end":8.94,"text":"one So what kinds of things do people learn and do here?","coverage":1},{"start":10.8,"end":14.92,"text":"two Are there any things you don't like about it?","coverage":1},{"start":16.84,"end":17.64,"text":"three","coverage":1},{"start":18.2,"end":21.38,"text":"Do you have many people here from other countries?","coverage":1}],"file":"cadd00414008e66837d9.js","track":0,"media":"../assets/media/fd35f29335a7295adf34b3bc8ac90d93556ff2d513ca30f629bc998e74845ff8.mp3"}]};
window.SCHOOL_SOURCE_ANSWERS=[{"text":"1  The artist made an ice sculpture of a horse.","slide":10,"shape":"8","bookPage":"38"},{"text":"2  The shops advertise the festival on posters.","slide":10,"shape":"9","bookPage":"38"},{"text":"3  Ice will melt when the weather gets warmer.","slide":10,"shape":"10","bookPage":"38"},{"text":"4  The museum has a display of pictures.","slide":10,"shape":"11","bookPage":"38"},{"text":"5  Tourism helps the city’s economy.","slide":10,"shape":"12","bookPage":"38"},{"text":"6  The ice figure looks like a person.","slide":10,"shape":"13","bookPage":"38"},{"text":"1 What weather is good or bad for going to festivals? Why?Possible answer: Dry weather is useful for outdoor festivals, but snow is good for an ice festival.","slide":12,"shape":"14","bookPage":"38"},{"text":"2 What are some things people can do in snowy or cold weather?Possible answer: People can skate, ski or make snow sculptures.","slide":12,"shape":"16","bookPage":"38"},{"text":"Exercise 2, Question 1: What country do you think this festival is in? Why?Answer: China; it is the Harbin Ice Festival.","slide":21,"shape":"17","bookPage":"39"},{"text":"Exercise 2, Question 2: What types of sculptures are there?Answer: Ice buildings, animals, people and cultural figures.","slide":21,"shape":"19","bookPage":"39"},{"text":"Exercise 2, Question 3: Do you think many people go to this festival? Why / Why not?Answer: Yes. About a million visitors come.","slide":21,"shape":"6","bookPage":"39"},{"text":"Exercise 3, Question 1: What is this festival and where is it?Answer: The Harbin Ice Festival in Harbin, China.","slide":22,"shape":"17","bookPage":"39"},{"text":"Exercise 3, Question 2: Where does the ice come from?Answer: The Songhua River.","slide":22,"shape":"19","bookPage":"39"},{"text":"Exercise 3, Question 3: What activities can people do at the festival?Answer: See ice sculptures and buildings, skate, bike, take horse rides and use ice slides.","slide":22,"shape":"6","bookPage":"39"},{"text":"Exercise 4, Statement 1: This festival started in 1995.Answer: False. It started in 1985.","slide":23,"shape":"12","bookPage":"39"},{"text":"Exercise 4, Statement 2: Harbin is in Siberia.Answer: False. Harbin is in China.","slide":23,"shape":"14","bookPage":"39"},{"text":"Exercise 4, Statement 3: The festival opens in January.Answer: True.","slide":23,"shape":"6","bookPage":"39"},{"text":"Exercise 4, Statement 4: The tallest ice building at the festival was 13 metres.Answer: False. It was over 30 metres.","slide":24,"shape":"12","bookPage":"39"},{"text":"Exercise 4, Statement 5: The visitors spend a lot of money.Answer: True.","slide":24,"shape":"14","bookPage":"39"},{"text":"Exercise 5, Item 1: largest ice festivalAnswer: c. a series of special events and performances over several days","slide":24,"shape":"6","bookPage":"39"},{"text":"Exercise 5, Item 2: completely frozenAnswer: b. turned into ice","slide":25,"shape":"12","bookPage":"39"},{"text":"Exercise 5, Item 3: amazingAnswer: b. very surprising","slide":25,"shape":"14","bookPage":"39"},{"text":"Exercise 5, Item 4: attracts visitorsAnswer: a. makes people go there by being interesting and enjoyable","slide":25,"shape":"6","bookPage":"39"},{"text":"1 What do you like about this festival? Why?Possible answer: I like the sculptures because they change colour when the lights come on.","slide":27,"shape":"14","bookPage":"39"},{"text":"2 Is there a festival like this, or another type of festival, where you live?Possible answer: There is a lantern festival where I live. We enjoy the lights at night.","slide":27,"shape":"16","bookPage":"39"},{"text":"We listened and took notes while the professor gave the lecture.Answer: b. a formal talk about a subject","slide":37,"shape":"13","bookPage":"40"},{"text":"There were many activities at the festival, such as watching shows or playing games.Answer: a. things you do for enjoyment, especially organized events","slide":37,"shape":"15","bookPage":"40"},{"text":"We wear traditional clothes at the festival. The clothes are very similar to the clothes my grandparents wore to the festival when they were young.Answer: a. part of older ways of doing things and older ideas","slide":38,"shape":"13","bookPage":"40"},{"text":"If a festival is about culture, tourists often enjoy going to it because they can learn about the local community’s way of life.Answer: a. habits and traditions of a country or group of people","slide":38,"shape":"15","bookPage":"40"},{"text":"A popular type of entertainment at a festival is watching a race or competition.Answer: a. shows, films, games or other ways of having fun","slide":39,"shape":"13","bookPage":"40"},{"text":"We enjoyed the delicious food.Answer: a. got pleasure from something","slide":39,"shape":"15","bookPage":"40"},{"text":"1  The Vivid Sydney festival — Photo c\n2  Muscat Nights — Photo b\n3  Cherry Blossom Festival — Photo a","slide":42,"shape":"6","bookPage":"41"},{"text":"Exercise 4 — Match each festival to its photo.1 The Vivid Sydney festival — Photo c2 Muscat Nights — Photo b3 Cherry Blossom Festival — Photo a","slide":43,"shape":"11","bookPage":"41"},{"text":"Exercise 5: Predict activities from the photos and festival names. Possible answer: attend talks in Sydney, enjoy music at Muscat Nights, and see cherry blossoms in Japan.","slide":43,"shape":"12","bookPage":"41"},{"text":"lecture     activities     traditional     culture     entertainment     enjoyed","slide":44,"shape":"7","bookPage":"41"},{"text":"1 Date: The festival is in May and June.Short notes: May and June","slide":46,"shape":"14","bookPage":"41"},{"text":"2 Activities: You can see art and you can eat different food.Short notes: see art; eat different food","slide":46,"shape":"15","bookPage":"41"},{"text":"Months: (10) January and (11) February","slide":52,"shape":"8","bookPage":"42"},{"text":"Activities: watch (12) sports (basketball and racing); listen to traditional (13) music; go to a\n(14) fashion show; eat traditional food","slide":52,"shape":"9","bookPage":"42"},{"text":"Exercise 9, 4 People can learn about Oman’s culture at Muscat Nights. Answer: True.","slide":53,"shape":"18","bookPage":"42"},{"text":"Exercise 9, 5 Nasrra was able to go to a fashion show at Muscat Nights. Answer: False. She has decided to go, but has not gone yet.","slide":53,"shape":"20","bookPage":"42"},{"text":"I went to a lecture about the sea.","slide":55,"shape":"13","bookPage":"43"},{"text":"1 So, what kinds of things do people learn and do here?","slide":57,"shape":"18","bookPage":"43"},{"text":"2 Are there any things you don’t like about it?","slide":57,"shape":"20","bookPage":"43"},{"text":"3 Do you have many people here from other countries?","slide":57,"shape":"6","bookPage":"43"},{"text":"1 What activities do people do at festivals in their free time?","slide":59,"shape":"17","bookPage":"43"},{"text":"2 Which festival is good for people with lots of hobbies?","slide":59,"shape":"19","bookPage":"43"},{"text":"3 What did you do at the Cherry Blossom Festival last weekend?","slide":59,"shape":"6","bookPage":"43"},{"text":"Place: Sydney, (1) Australia","slide":60,"shape":"7","bookPage":"42"},{"text":"Months: (2) May and June","slide":60,"shape":"8","bookPage":"42"},{"text":"Activities: learn about (3) nature, for example, new ways to clean the sea; walk through a 3D (4) art show; listen to a (5) talk about food","slide":60,"shape":"9","bookPage":"42"},{"text":"Month: (6) April","slide":61,"shape":"8","bookPage":"42"},{"text":"Activities: have a picnic under the cherry trees; eat at food (7) stalls; go on the (8) lake in a boat; visit (9) museums","slide":61,"shape":"9","bookPage":"42"},{"text":"1. Vivid Sydney has taken place every year since 2009.","slide":64,"shape":"5","bookPage":null},{"text":"11. What is one reason the reporter says many people can join Vivid Sydney?\nA. Visitors can enter all lectures for a reduced price.\nB. Visitors can get transport included in their tickets.\nC. Visitors can join many activities without paying.","slide":64,"shape":"8","bookPage":null},{"text":"1 My city is having a festival to celebrate local culture.celebrate — do something fun for a special occasion","slide":76,"shape":"13","bookPage":"48"},{"text":"2 The people in the video are wearing costumes that look like clothing from long ago.costumes — clothes to look like somebody else","slide":76,"shape":"14","bookPage":"48"},{"text":"3 A favourite dish for breakfast in Canada is pancakes with maple syrup.dish — one part of a meal","slide":76,"shape":"15","bookPage":"48"},{"text":"4 For parties, my sister bakes cookies and decorates them with pretty colours.decorates — makes something look pretty","slide":76,"shape":"5","bookPage":"48"},{"text":"5 I love colourful fireworks, but the loud sounds scare my cats.fireworks — objects that explode with light and noise","slide":77,"shape":"13","bookPage":"48"},{"text":"6 Some people give small gifts to their children on their graduation day, like money or books.gifts — special things given to others","slide":77,"shape":"14","bookPage":"48"},{"text":"7 Every year, there is a big parade through the city streets for the festival.parade — people or vehicles moving through streets to celebrate","slide":77,"shape":"15","bookPage":"48"},{"text":"PredictionsThey might discuss fireworks, a parade and a special meal.","slide":79,"shape":"12","bookPage":"48"},{"text":"North American holiday: Thanksgiving","slide":84,"shape":"7","bookPage":"49"},{"text":"US and Canada celebrate – everyone thankful","slide":84,"shape":"8","bookPage":"49"},{"text":"traditional meal: turkey, stuffing, potatoes, corn, cranberries, pie","slide":84,"shape":"10","bookPage":"49"},{"text":"Canada\nUS\npumpkin pie: spicy\nstuffing: rice or bread\npumpkin pie: sweet, whipped cream\nstuffing: cornbread, oysters","slide":84,"shape":"26","bookPage":"49"},{"text":"decorations: leaves, autumn vegetables, candles","slide":85,"shape":"7","bookPage":"49"},{"text":"special activities: parades, watch sports on TV, no gifts","slide":85,"shape":"8","bookPage":"49"},{"text":"Different reasons for the holiday:","slide":85,"shape":"11","bookPage":"49"},{"text":"1 (F) Ali: Which is the best North American holiday or celebration?","slide":91,"shape":"12","bookPage":"49"},{"text":"2 (C) Paul: Hmm. Well, I like Independence Day in the US because of the fireworks and New Year’s Eve often has fireworks, too. But I think the best holiday is Thanksgiving.","slide":91,"shape":"13","bookPage":"49"},{"text":"3 (K) Ali: Why do you like Thanksgiving?","slide":91,"shape":"14","bookPage":"49"},{"text":"4 (E) Paul: Everyone has something to be thankful for, so everyone can celebrate it.","slide":91,"shape":"15","bookPage":"49"},{"text":"5 (H) Ali: How do people celebrate it?","slide":91,"shape":"6","bookPage":"49"},{"text":"6 (A) Paul: Well, most people get together with family and friends and have a big meal.","slide":92,"shape":"12","bookPage":"49"},{"text":"7 (B) Ali: What do they eat?","slide":92,"shape":"13","bookPage":"49"},{"text":"8 (I) Paul: They usually eat a traditional meal. This is usually a delicious turkey with stuffing for the main dish. Most traditional Thanksgiving meals have food which is from the Americas, like potatoes, corn and cranberries. For dessert, they eat pumpkin pie, but some people prefer different kinds of pie, like apple.","slide":92,"shape":"14","bookPage":"49"},{"text":"9 (D) Ali: That all sounds delicious. Are there any special decorations for Thanksgiving?","slide":92,"shape":"15","bookPage":"49"},{"text":"10 (L) Paul: Well, people often decorate their dinner tables and homes with things such as colourful leaves, autumn vegetables and candles.","slide":93,"shape":"13","bookPage":"49"},{"text":"11 (J) Ali: Do people give gifts or do some special activities?","slide":93,"shape":"14","bookPage":"49"},{"text":"12 (G) Paul: Well, people don’t really give gifts, but there are some special activities. For example, both countries celebrate with parades with marching bands and people in costumes.","slide":93,"shape":"15","bookPage":"49"},{"text":"Example exchangeA: Which celebration do you like best?B: I like New Year best.A: How do people celebrate it?B: We eat a special meal with family and friends.A: Do people give gifts?B: Some families do.","slide":99,"shape":"12","bookPage":"50"},{"text":"2 Do people try mainly one type of thing?","slide":105,"shape":"15","bookPage":"44"},{"text":"3 Are you ever bored?","slide":105,"shape":"6","bookPage":"44"},{"text":"1 Do you like festivals?","slide":107,"shape":"10","bookPage":"45"},{"text":"2 When do you go home?","slide":107,"shape":"11","bookPage":"45"},{"text":"3 Are you a good cook?","slide":107,"shape":"12","bookPage":"45"},{"text":"1 Where’s he sitting?","slide":114,"shape":"16","bookPage":"46"},{"text":"2 I’m cooking at the moment.","slide":114,"shape":"17","bookPage":"46"},{"text":"3 Are you going home now?","slide":114,"shape":"18","bookPage":"46"},{"text":"4 She’s speaking to her brother.","slide":114,"shape":"5","bookPage":"46"},{"text":"5 What are you making?","slide":114,"shape":"6","bookPage":"46"},{"text":"6 Is the music playing right now?","slide":114,"shape":"7","bookPage":"46"},{"text":"6  What does that machine do?\nWhat is that machine doing right now?","slide":117,"shape":"6","bookPage":"46"},{"text":"7  My friends and I watch sports.\nMy friends and I are watching sports now.","slide":117,"shape":"7","bookPage":"46"},{"text":"8  Why does he walk to school?\nWhy is he walking to school today?","slide":117,"shape":"8","bookPage":"46"},{"text":"Example exchangeA: I’m watching a parade. What are you doing?B: I’m waiting near the food stalls. Are you enjoying it?A: Yes, I am. The musicians are playing traditional music.","slide":119,"shape":"12","bookPage":"46"},{"text":"go toa festival; a concert; a celebration; an event; a lecture; a party; university","slide":123,"shape":"16","bookPage":"47"},{"text":"takea photo; care (of); part; place; your time","slide":123,"shape":"18","bookPage":"47"},{"text":"havea nice time; a celebration; an event; fun; a lecture; a party; a problem","slide":123,"shape":"6","bookPage":"47"},{"text":"1  Excuse me, can you take a photo of my sister and me?","slide":125,"shape":"6","bookPage":"47"},{"text":"2  What time will you leave your house to go to the celebration?","slide":125,"shape":"7","bookPage":"47"},{"text":"3  I’m going on holiday next week. Will you take care of my plants?","slide":125,"shape":"8","bookPage":"47"},{"text":"4  Have a nice time on your holiday!","slide":125,"shape":"9","bookPage":"47"},{"text":"5  I’m sorry that I can’t go to the party tonight. But I hope you have fun!","slide":125,"shape":"10","bookPage":"47"},{"text":"1  What do you think makes a good festival? Should everybody go to every event or is it\nOK to miss some of them?","slide":127,"shape":"6","bookPage":"47"},{"text":"2  Do you take your time to enjoy a festival when you go or do you hurry to see things?","slide":127,"shape":"7","bookPage":"47"},{"text":"3  In your country, do people often go to concerts to listen to music?","slide":127,"shape":"8","bookPage":"47"},{"text":"4  If it’s a special day, do you have a party / celebration?","slide":127,"shape":"9","bookPage":"47"},{"text":"Exercise 10I take my time at a festival because I want to enjoy each activity.","slide":128,"shape":"15","bookPage":"47"},{"text":"People are wearing bright costumes.","slide":132,"shape":"6","bookPage":null},{"text":"When does the festival start?","slide":132,"shape":"9","bookPage":null},{"text":"We have just reached the square. The festival is starting now. A band is playing at the festival. Its music sounds great.","slide":133,"shape":"6","bookPage":null},{"text":"My sister has found something fun to do. She is making a paper hat. The hat needs some colour. So she is adding a red ribbon.","slide":134,"shape":"6","bookPage":null},{"text":"A short parade is moving along the street. Visitors are watching the costumes.","slide":135,"shape":"7","bookPage":null},{"text":"One person in the parade is wearing a bright costume. A visitor could take a photo of it.","slide":136,"shape":"7","bookPage":null},{"text":"1. More than two million people sometimes attend, showing that the festival is getting bigger.","slide":141,"shape":"5","bookPage":null},{"text":"11. What does the number of visitors suggest about Vivid Sydney?\nA. It is becoming more popular but attracting fewer people.\nB. It is becoming more popular and attracting larger crowds.\nC. It has stayed the same size since it began.","slide":141,"shape":"8","bookPage":null},{"text":"1. Vivid Sydney lasts for three weeks.\nAnswer: TRUE","slide":144,"shape":"5","bookPage":null},{"text":"11. Muscat Nights is held in January and February.\nAnswer: TRUE","slide":144,"shape":"8","bookPage":null},{"text":"Our friends are decorating the hall.","slide":153,"shape":"6","bookPage":null},{"text":"The festival takes place in June.","slide":153,"shape":"9","bookPage":null},{"text":"We decide to try something new today. A volunteer explains the game to us. After her explanation, we choose a team. Our team is now waiting for its turn.","slide":154,"shape":"6","bookPage":null},{"text":"We only have an hour at the festival. We first go to the small exhibition. After visiting it, we watch a dance show. The show finishes just before we leave.","slide":155,"shape":"6","bookPage":null},{"text":"A dancer is performing outdoors in traditional clothes. People are watching the activity. They may enjoy learning about local culture.","slide":156,"shape":"7","bookPage":null},{"text":"A visitor can watch the dance first. Then they can take part in another festival activity. This is a good way to spend time there.","slide":157,"shape":"7","bookPage":null},{"text":"Choice and reasonI would choose the parade because I enjoy seeing traditional costumes andlearning about different cultures.","slide":164,"shape":"12","bookPage":"51"},{"text":"Parades and foodParades: interesting costumes, but crowded.Food: try new dishes, but you may not like every dish.","slide":167,"shape":"17","bookPage":"52"},{"text":"Super Sale, fireworks and showsCheap shopping and colourful fireworks, but parking may be difficult.Famous performers, but you need to plan which shows to see.","slide":167,"shape":"19","bookPage":"52"},{"text":"Your final choiceI still prefer the parade. We can arrive early to find a good place.","slide":168,"shape":"18","bookPage":"52"},{"text":"events\npositives\nnegatives\nparades\ntraditional costumes\nvery crowded\nfood\ntry new dishes\nmay not like every dish\nSuper Sale and fireworks\ncheap shopping and colourful fireworks\nparking may be difficult\nshows\nfamous performers\nneed to plan which shows to see","slide":169,"shape":"14","bookPage":"52"},{"text":"What features of the UAE National Day poster help you decide whether to go?Possible answer: The photo, activity descriptions and direct invitations attract attention.","slide":175,"shape":"15","bookPage":"53"},{"text":"1 What are possible positives of the events in the poster?Possible answer: Visitors can learn history, hear music, make art and enjoy races.","slide":175,"shape":"16","bookPage":"53"},{"text":"2 What would you change to make the poster more persuasive?Possible answer: I would add exact times and ticket information.","slide":175,"shape":"17","bookPage":"53"},{"text":"1 Put the words in order: this / could / You / online / look at / .You could look at this online.","slide":179,"shape":"13","bookPage":"54"},{"text":"2 Put the words in order: starting / How / cake / ? / with / aboutHow about starting with cake?","slide":179,"shape":"14","bookPage":"54"},{"text":"3 Put the words in order: not / Why / yourself / ? / try itWhy not try it yourself?","slide":179,"shape":"15","bookPage":"54"},{"text":"Which phrases make suggestions?Can we think about trying this?How about trying this?I’d suggest trying this.Shall we try this?","slide":180,"shape":"14","bookPage":"54"},{"text":"infinitive without to\nverb + -ing\n1 You could ...2 Why not ...?3 Shall we ...?\n4 How about ...?5 I’d suggest ...6 Can we think about ...?","slide":181,"shape":"13","bookPage":"54"},{"text":"Example suggestionsYou could arrive early.How about trying some traditional food?Shall we watch the parade?","slide":183,"shape":"12","bookPage":"54"},{"text":"Woman: (1) Shall we go to the food tent? I’d like to get some pizza.","slide":189,"shape":"7","bookPage":"55"},{"text":"Man: OK. Good idea. After that (2) how about visiting the art exhibition? I’d like to see some of the paintings.","slide":189,"shape":"8","bookPage":"55"},{"text":"Woman: Yeah, that sounds good. Then we (3) could go and do a singing workshop.","slide":189,"shape":"9","bookPage":"55"},{"text":"A possible exchangeA: How about going to the parade? We can see traditional costumes and learnabout different cultures.B: I’m not sure. Is it very crowded?A: Yes, but we could arrive early. There are also fireworks on the main day.B: That sounds good. Let’s go early.","slide":201,"shape":"12","bookPage":"56"},{"text":"Example reportOur group chose the parade because we want to see traditional costumes andfireworks. We decided to arrive early because it may be crowded.","slide":203,"shape":"12","bookPage":"57"},{"text":"Why do we not try the food event?","slide":207,"shape":"6","bookPage":null},{"text":"The dance show offers something for everyone.","slide":207,"shape":"9","bookPage":null},{"text":"We need an idea that suits the whole group. I think we should try the craft workshop. The workshop lets us make small gifts. We could give those gifts to our families.","slide":208,"shape":"6","bookPage":null},{"text":"I can see why you like the concert. I would rather choose the food event. That event has dishes from several countries. Trying those dishes would be new for us.","slide":209,"shape":"6","bookPage":null},{"text":"I think our group should choose this music event. A small stage gives the performers a clear place to play. The listeners can sit together near the stage. It looks like a friendly activity for our group.","slide":210,"shape":"7","bookPage":null},{"text":"A lecture may give useful information, but I prefer this music event. The performers are on a small stage, and the listeners can enjoy the show together. I think it offers more entertainment. We could choose it for our evening plan.","slide":211,"shape":"7","bookPage":null}];
